<script setup>
import {computed,ref,watch} from 'vue';
import {useAgencyStore} from '../../store/agency.js';
import {useRoute} from 'vue-router';
import api from '../../services/api.js';
const props=defineProps({agencyId:[Number,String],http:Object,schedulePath:String});
const agency=useAgencyStore(),route=useRoute();
const id=computed(()=>Number(props.agencyId||agency.currentAgency?.id)),client=computed(()=>props.http||api);
const students=ref([]),selected=ref(null),overview=ref(null),loading=ref(false),detailLoading=ref(false),error=ref('');let generation=0,detailGeneration=0;
async function load(){const current=++generation;detailGeneration++;students.value=[];selected.value=null;overview.value=null;error.value='';if(!id.value)return;loading.value=true;try{const {data}=await client.value.get('/tutoring-workspace/students',{params:{agencyId:id.value}});if(current===generation)students.value=data.students||[];}catch(e){if(current===generation)error.value=e.response?.data?.error?.message||'Students could not be loaded.';}finally{if(current===generation)loading.value=false;}}
async function open(student){const current=++detailGeneration;selected.value=student;overview.value=null;error.value='';detailLoading.value=true;try{const {data}=await client.value.get(`/tutoring-learning-os/clients/${student.id}/overview`,{params:{agencyId:id.value}});if(current===detailGeneration)overview.value=data;}catch(e){if(current===detailGeneration)error.value=e.response?.data?.error?.message||'This learning record could not be opened.';}finally{if(current===detailGeneration)detailLoading.value=false;}}
const schedule=computed(()=>props.schedulePath||`${route.params.organizationSlug?'/'+route.params.organizationSlug:''}/dashboard?tab=my_schedule`);
watch(id,load,{immediate:true});
</script>
<template><main class="tutor-students"><h1>My students</h1><p>Your assigned tutoring students and their learning plans.</p><RouterLink :to="schedule">Open tutoring schedule</RouterLink><p v-if="loading" role="status">Loading students…</p><p v-if="error" role="alert">{{error}} <button @click="selected?open(selected):load()">Try again</button></p><p v-if="!loading&&!error&&!students.length">No students are assigned to you for tutoring in this agency yet.</p><ul v-if="students.length"><li v-for="student in students" :key="student.id"><button @click="open(student)" :aria-pressed="selected?.id===student.id">{{student.displayName}}</button></li></ul><section v-if="selected"><h2>{{selected.displayName}} · Learning</h2><p v-if="detailLoading" role="status">Loading learning record…</p><template v-if="overview"><p v-if="!overview.subjects?.length">No subject learning plan has been created yet. Open the student’s scheduled tutoring session to begin the learning workflow.</p><article v-for="item in overview.subjects" :key="item.subject.id"><h3>{{item.subject.subject_label||item.subject.subject_key}}</h3><p>{{item.activePlan?'Current learning plan':'No active learning plan'}}</p><ul><li v-for="goal in item.goals" :key="goal.id">{{goal.goal_text||goal.description||goal.title}}</li></ul><p>Progress: {{item.progressPct??0}}%</p></article></template></section></main></template>
<style scoped>.tutor-students{max-width:900px;margin:auto;padding:24px;color:var(--text-primary,#203b5b)}p{line-height:1.6}li{margin:9px 0}button{font:inherit;min-height:44px;padding:10px 16px;background:#eef5fd;border:1px solid #b3cbe5;border-radius:8px;cursor:pointer}button[aria-pressed=true]{background:#d2e6fb}article{padding:16px;border:1px solid #d4e0eb;border-radius:10px;margin:12px 0}[role=alert]{color:#a52d37}:focus-visible{outline:3px solid #4e86c9;outline-offset:2px}</style>
